import {isReducedMotion,motionPreference,setMotionPreference,motionDescription} from './motion.js?v=0.90.52';
// One choreographed opening, with held drawings at eight frames per second.
export const OPENING_FRAMES=104;
export function duelFrame(frame){const f=Math.max(0,Math.min(OPENING_FRAMES-1,frame)),leftStrike=f===6||f===7,rightStrike=f===18||f===19;const iceCharge=f>=24&&f<30,iceBeam=f>=30&&f<44,ghostCharge=f>=50&&f<62,ghostBurst=f>=62&&f<78,ghostWash=f>=78;return {leftPose:leftStrike||ghostBurst?2:f>=4&&f<6||ghostCharge?1:rightStrike||iceBeam?3:0,rightPose:rightStrike?2:f>=16&&f<18||iceCharge?1:leftStrike||ghostBurst?3:0,leftX:leftStrike?48:f===8?20:rightStrike?-8:iceBeam?-10:ghostBurst?12:0,rightX:rightStrike?-48:f===20?-20:leftStrike?8:ghostBurst?12:0,leftStrike,rightStrike,iceCharge,iceBeam,ghostCharge,ghostBurst,ghostWash,titleReveal:f>=88,stage:f<24?'slashes':f<30?'ice-charge':f<44?'ice-beam':f<50?'ice-recoil':f<62?'ghost-charge':f<78?'ghost-burst':f<88?'ghost-wash':'title-reveal'};}
export function soldierFrame(frame,index){const phase=(frame+index*5)%32,type=Math.floor(index/2)%3;let pose=0,x=0,y=0,rotation=0,attack='';if(type===0){pose=phase<7?0:phase<11?1:phase<14?2:phase<18?3:0;attack=phase>=11&&phase<14?'overhead':'';y=pose===1?-5:pose===2?2:0;rotation=pose===2?(index<3?-12:12):0;}else if(type===1){pose=phase<5?0:phase<8?1:phase<12?2:phase<15?3:0;attack=phase>=8&&phase<12?'thrust':'';x=pose===2?18:pose===3?-5:0;}else{pose=phase<5?3:phase<8?1:phase<11?2:phase<14?0:phase<17?1:phase<20?2:0;attack=pose===2?'sweep':'';x=pose===2?10:pose===3?-6:0;y=pose===2?-3:0;rotation=pose===2?(phase<14?-18:16):0;}return {pose,x:x*(index<3?1:-1),y,rotation,attack};}
export function animateDuel(root,{onReveal=()=>{},onComplete=()=>{}}={}){let raf=0,last=-1,start=null,revealed=false;const reduced=()=>isReducedMotion();const left=root.querySelector('.duelist-left'),right=root.querySelector('.duelist-right');const poseArt=new Image();poseArt.onload=()=>root.classList.add('duel-art-ready');poseArt.src='assets/duel-poses.webp';
 function paint(frame){const d=duelFrame(frame);left.style.setProperty('--pose',d.leftPose);right.style.setProperty('--pose',d.rightPose);left.style.transform=`translate(${d.leftX}%,${d.leftPose===1?-8:0}px) rotate(${d.leftPose===2?-8:d.leftPose===3?7:0}deg)`;right.style.transform=`translate(${d.rightX}%,${d.rightPose===1?-8:0}px) rotate(${d.rightPose===2?8:d.rightPose===3?-7:0}deg)`;root.dataset.duelFrame=String(frame);root.dataset.duelStage=d.stage;for(const [name,active] of Object.entries({'ghost-slash':d.leftStrike,'ice-slash':d.rightStrike,'ice-charging':d.iceCharge,'ice-beaming':d.iceBeam,'ghost-charging':d.ghostCharge,'ghost-bursting':d.ghostBurst,'ghost-washing':d.ghostWash}))root.classList.toggle(name,active);root.querySelectorAll('.distant-soldier').forEach((soldier,i)=>{const s=soldierFrame(frame,i);soldier.style.setProperty('--pose',s.pose);soldier.style.transform=`translate(${s.x}px,${s.y}px) rotate(${s.rotation}deg)`;soldier.dataset.attack=s.attack;soldier.classList.toggle('soldier-striking',!!s.attack);});if(d.titleReveal&&!revealed){revealed=true;onReveal();}}
 function tick(t){start??=t;const frame=Math.min(OPENING_FRAMES-1,Math.floor((t-start)/125));if(frame!==last){paint(frame);last=frame;}if(frame===OPENING_FRAMES-1){raf=0;onComplete();return;}raf=requestAnimationFrame(tick);}
 return {start(){this.stop();start=null;last=-1;revealed=false;if(reduced()){paint(0);return;}raf=requestAnimationFrame(tick);},stop(reset=true){cancelAnimationFrame(raf);raf=0;if(reset)paint(0);}};
}
